with open('c:/Users/LOQ/Downloads/Python_programs/privacy-vision-browser-agent/extension/src/popup/popup.ts', 'r') as f:
    content = f.read()

idx_start = content.index('function handleRunClick(): void {')
idx_end = content.index('// ============================================\n// EXPORTS')

print('Found section:', idx_end - idx_start, 'chars')

# Build new section using string concatenation to avoid quote issues
lines = []
lines.append('// ============================================')
lines.append('// RENDERING')
lines.append('// ============================================')
lines.append('')
lines.append('function renderAll(): void {')
lines.append('  renderWorkflow();')
lines.append('  renderCurrentAction();')
lines.append('  renderPrivacyShield();')
lines.append('  renderMetrics();')
lines.append('  renderActivity();')
lines.append('  updateStatusBar();')
lines.append('  updateFooterStatus();')
lines.append('  renderDebugPanel();')
lines.append('}')
lines.append('')
lines.append('function renderWorkflow(): void {')
lines.append("  const container = elements.workflowNodes;")
lines.append('  if (!container) return;')
lines.append('')
lines.append("  container.innerHTML = '';")
lines.append('')
lines.append('  WORKFLOW_NODES.forEach((node, index) => {')
lines.append('    const isCompleted = state.stages.includes(node.id);')
lines.append('    const isCurrent = state.currentStage === node.id;')
lines.append('    const isFuture = !isCompleted && !isCurrent;')
lines.append('')
lines.append("    const wrapper = document.createElement('div');")
lines.append("    wrapper.className = 'workflow-node' + (isCompleted ? ' completed' : '') + (isCurrent ? ' current' : '') + (isFuture ? ' future' : '');")
lines.append("    wrapper.style.setProperty('--node-index', index.toString());")
lines.append('')
lines.append('    if (node.isBoundary) {')
lines.append("      wrapper.classList.add('boundary');")
lines.append('    }')
lines.append('')
lines.append("    const iconSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');")
lines.append("    iconSvg.setAttribute('viewBox', '0 0 24 24');")
lines.append("    iconSvg.setAttribute('class', 'node-icon');")
lines.append("    iconSvg.innerHTML = '<path d=\"' + node.icon + '\" stroke=\"currentColor\" stroke-width=\"2\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>';")
lines.append('')
lines.append("    const labelDiv = document.createElement('div');")
lines.append("    labelDiv.className = 'node-label';")
lines.append("    labelDiv.innerHTML = '<span class=\"node-title\">' + node.label + '</span><span class=\"node-subtitle\">' + node.subtitle + '</span>';")
lines.append('')
lines.append('    wrapper.appendChild(iconSvg);')
lines.append('    wrapper.appendChild(labelDiv);')
lines.append('    container.appendChild(wrapper);')
lines.append('  });')
lines.append('')
lines.append('  // Network boundary line')
lines.append('  const boundary = elements.networkBoundary;')
lines.append('  if (boundary) {')
lines.append('    const boundaryIndex = WORKFLOW_NODES.findIndex(n => n.isBoundary);')
lines.append('    if (boundaryIndex >= 0) {')
lines.append("      boundary.style.setProperty('--boundary-index', boundaryIndex.toString());")
lines.append('    }')
lines.append('  }')
lines.append('}')
lines.append('')

new_section = '\n'.join(lines) + '\n\n'

new_content = content[:idx_start] + new_section + content[idx_end:]

with open('c:/Users/LOQ/Downloads/Python_programs/privacy-vision-browser-agent/extension/src/popup/popup.ts', 'w') as f:
    f.write(new_content)

print('Done! New length:', len(new_content))